#' RD Geographic / Two-Score Boundary
#'
#' 
#' @param data .
#' @param outcome .
#' @param treatment .
#' @param x1 .
#' @param x2 .
#' @param bx .
#' @param by .
#' @param cluster .
#' @param boundary .
#' @param c1 .
#' @param c2 .
#' @param p .
#' @param bwselect .
#' @param kernel .
#' @param vce .
#' @param level .
#' @param donut .
#' @param plot .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$design} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$est} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$mapPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$design$asDF}
#'
#' \code{as.data.frame(results$design)}
#'
#' @export
rdgeo <- function(
    data,
    outcome,
    treatment,
    x1,
    x2,
    bx,
    by,
    cluster,
    boundary = "polyline",
    c1 = 0,
    c2 = 0,
    p = 1,
    bwselect = "mserd",
    kernel = "triangular",
    vce = "nn",
    level = 95,
    donut = 0,
    plot = TRUE,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("rdgeo requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(treatment)) treatment <- jmvcore::resolveQuo(jmvcore::enquo(treatment))
    if ( ! missing(x1)) x1 <- jmvcore::resolveQuo(jmvcore::enquo(x1))
    if ( ! missing(x2)) x2 <- jmvcore::resolveQuo(jmvcore::enquo(x2))
    if ( ! missing(bx)) bx <- jmvcore::resolveQuo(jmvcore::enquo(bx))
    if ( ! missing(by)) by <- jmvcore::resolveQuo(jmvcore::enquo(by))
    if ( ! missing(cluster)) cluster <- jmvcore::resolveQuo(jmvcore::enquo(cluster))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(treatment), treatment, NULL),
            `if`( ! missing(x1), x1, NULL),
            `if`( ! missing(x2), x2, NULL),
            `if`( ! missing(bx), bx, NULL),
            `if`( ! missing(by), by, NULL),
            `if`( ! missing(cluster), cluster, NULL))


    options <- rdgeoOptions$new(
        outcome = outcome,
        treatment = treatment,
        x1 = x1,
        x2 = x2,
        bx = bx,
        by = by,
        cluster = cluster,
        boundary = boundary,
        c1 = c1,
        c2 = c2,
        p = p,
        bwselect = bwselect,
        kernel = kernel,
        vce = vce,
        level = level,
        donut = donut,
        plot = plot,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- rdgeoClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

